-- =============================================================================
-- V8: 系统/应用两级目录 + H5 公开盘点 + 用户来源标识
-- 日期: 2026-05-09
-- 背景: 引入公司真实 197 系统 / 264 子系统目录,作为盘点的唯一选择来源;
--      H5 公开链接面向责任人,首次提交自动创建账号(姓名+手机号去重);
--      盘点表新增 system_catalog_id / application_catalog_id / submit_source。
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- 1. 系统目录(一级)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS t_application_catalog;
DROP TABLE IF EXISTS t_system_catalog;

CREATE TABLE t_system_catalog (
    id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
    system_code VARCHAR(64) NOT NULL UNIQUE COMMENT '系统编号',
    system_name VARCHAR(128) NOT NULL COMMENT '系统名称',
    system_alias VARCHAR(128) COMMENT '系统别名',
    unit VARCHAR(64) COMMENT '单位',
    category VARCHAR(32) COMMENT '系统分类(应用系统/网络与信息安全系统/数智化基础平台/运营支撑系统)',
    domain_l1 VARCHAR(64) COMMENT '一级域',
    domain_l2 VARCHAR(64) COMMENT '二级域',
    domain_l3 VARCHAR(64) COMMENT '三级域',
    status VARCHAR(20) NOT NULL DEFAULT 'IN_USE' COMMENT '状态(IN_USE/OFFLINE/OFFLINE_REFERENCE/BUILDING)',
    description TEXT COMMENT '系统描述',
    has_applications TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否包含子系统',
    vendor VARCHAR(128) COMMENT '开发厂商',
    level VARCHAR(32) COMMENT '系统等级',
    responsible_dept VARCHAR(64) COMMENT '责任部门',
    responsible_person VARCHAR(64) COMMENT '系统级责任人',
    responsible_phone VARCHAR(20) COMMENT '系统级联系方式',
    online_date DATE COMMENT '上线时间',
    build_mode VARCHAR(20) COMMENT '系统建设模式(委外/委内/自研/内部能力引入)',
    tags VARCHAR(255) COMMENT '系统标签',
    enabled TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_status (status),
    INDEX idx_unit (unit),
    INDEX idx_dept (responsible_dept),
    INDEX idx_enabled (enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统资产目录(一级)';

-- -----------------------------------------------------------------------------
-- 2. 应用目录(二级,可选)
-- -----------------------------------------------------------------------------
CREATE TABLE t_application_catalog (
    id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键ID',
    application_code VARCHAR(64) NOT NULL UNIQUE COMMENT '子系统编码',
    system_code VARCHAR(64) NOT NULL COMMENT '关联系统编号',
    application_name VARCHAR(128) NOT NULL COMMENT '子系统名称',
    status VARCHAR(20) NOT NULL DEFAULT 'IN_USE' COMMENT '状态',
    description TEXT COMMENT '子系统描述',
    vendor VARCHAR(128) COMMENT '开发厂商',
    responsible_person VARCHAR(64) COMMENT '责任人',
    responsible_phone VARCHAR(20) COMMENT '联系电话',
    enabled TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_system_code (system_code),
    INDEX idx_status (status),
    INDEX idx_enabled (enabled),
    CONSTRAINT fk_app_system FOREIGN KEY (system_code) REFERENCES t_system_catalog(system_code) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='应用目录(二级,可选)';

-- -----------------------------------------------------------------------------
-- 3. 用户表新增 department / source 字段(支持 H5 自填)
--    幂等:重复执行不报错(使用 information_schema 判断列是否已存在)
-- -----------------------------------------------------------------------------
SET @col_exists := (SELECT COUNT(*) FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 't_user' AND column_name = 'department');
SET @sql := IF(@col_exists = 0,
               'ALTER TABLE t_user ADD COLUMN department VARCHAR(64) COMMENT ''部门'' AFTER phone',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 't_user' AND column_name = 'source');
SET @sql := IF(@col_exists = 0,
               'ALTER TABLE t_user ADD COLUMN source VARCHAR(20) NOT NULL DEFAULT ''INTERNAL'' COMMENT ''来源(INTERNAL/H5_SELF_REGISTER)'' AFTER department',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @idx_exists := (SELECT COUNT(*) FROM information_schema.statistics
                    WHERE table_schema = DATABASE() AND table_name = 't_user' AND index_name = 'idx_user_realname_phone');
SET @sql := IF(@idx_exists = 0,
               'ALTER TABLE t_user ADD INDEX idx_user_realname_phone (real_name, phone)',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- -----------------------------------------------------------------------------
-- 4. 盘点表关联两级目录 + 提交来源
-- -----------------------------------------------------------------------------
SET @col_exists := (SELECT COUNT(*) FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 't_inventory_record' AND column_name = 'system_catalog_id');
SET @sql := IF(@col_exists = 0,
               'ALTER TABLE t_inventory_record ADD COLUMN system_catalog_id BIGINT COMMENT ''系统目录ID'' AFTER business_system_id',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 't_inventory_record' AND column_name = 'application_catalog_id');
SET @sql := IF(@col_exists = 0,
               'ALTER TABLE t_inventory_record ADD COLUMN application_catalog_id BIGINT COMMENT ''应用目录ID'' AFTER system_catalog_id',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 't_inventory_record' AND column_name = 'submit_source');
SET @sql := IF(@col_exists = 0,
               'ALTER TABLE t_inventory_record ADD COLUMN submit_source VARCHAR(20) NOT NULL DEFAULT ''INTERNAL'' COMMENT ''提交来源(INTERNAL/H5)'' AFTER source_type',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @idx_exists := (SELECT COUNT(*) FROM information_schema.statistics
                    WHERE table_schema = DATABASE() AND table_name = 't_inventory_record' AND index_name = 'idx_inv_system_catalog');
SET @sql := IF(@idx_exists = 0,
               'ALTER TABLE t_inventory_record ADD INDEX idx_inv_system_catalog (system_catalog_id)',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @idx_exists := (SELECT COUNT(*) FROM information_schema.statistics
                    WHERE table_schema = DATABASE() AND table_name = 't_inventory_record' AND index_name = 'idx_inv_app_catalog');
SET @sql := IF(@idx_exists = 0,
               'ALTER TABLE t_inventory_record ADD INDEX idx_inv_app_catalog (application_catalog_id)',
               'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- -----------------------------------------------------------------------------
-- 5. 系统目录管理权限
-- -----------------------------------------------------------------------------
INSERT INTO t_permission (parent_id, permission_code, permission_name, resource_type, action, path, icon, sort_order, description, created_at, updated_at) VALUES
    (NULL, 'system-catalog:read',   '系统目录查看', 'system-catalog', 'read',   '/system-catalog',         'Folder',     50, '查看系统/应用两级目录', NOW(), NOW()),
    (NULL, 'system-catalog:update', '系统目录编辑', 'system-catalog', 'update', '/system-catalog/update',  'FolderEdit', 51, '启用/停用系统或应用',   NOW(), NOW())
ON DUPLICATE KEY UPDATE
    permission_name = VALUES(permission_name),
    description     = VALUES(description),
    updated_at      = NOW();

-- 把新权限授予 admin
INSERT INTO t_role_permission (role_id, permission_id, created_at, updated_at)
SELECT r.id, p.id, NOW(), NOW()
FROM t_role r, t_permission p
WHERE r.role_code = 'ROLE_SYSTEM_ADMIN'
  AND p.permission_code IN ('system-catalog:read', 'system-catalog:update')
ON DUPLICATE KEY UPDATE updated_at = NOW();

