    ('SDYYBY0005-QC', '山东业务集中稽核系统', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '计费账务系统', 'BOSS系统', 'IN_USE', '山东移动业务集中稽核系统聚焦市场业务、政企业务、家庭业务、新兴等业务，汇聚CRM、经分、无纸化等各类数据源，根据业务规则及管理规范，进行加工比对，并按照稽核流程派发工单，确保相关业务资料的真实性、完整性、有效性，促进和提升业务办理的合规性。', 1, NULL, NULL, '数智化部', NULL, NULL, '2018-10-01', '委外', NULL),
