    ('SDYYBY0010-QC', '信安管控平台', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '大数据应用系统', '其他大数据应用系统', 'IN_USE', NULL, 1, NULL, NULL, '数智化部', NULL, NULL, '2020-09-01', '委外', NULL),
    ('SDYYBY0002-QC', '经营分析系统', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '大数据应用系统', '市场营销和业务决策', 'IN_USE', '以市场部、财务部、集客部、地市公司等业务部门数据支撑需求，实现应用注智、数据赋能，提供KPI、决策分析、掌上经分、自助分析、自助报表、挖掘分析等手段在CHBN领域提供全场景、全周期的业务分析、决策支持、营销支撑。', 1, NULL, NULL, '数智化部', NULL, NULL, '2004-10-01', '委外', NULL),
    ('SDYYBY0025-QC', '营销管控平台', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '大数据应用系统', '其他大数据应用系统', 'IN_USE', '实现了全量资费的梳理，实现资费上线、下线流程标准化，加强资费生命周期监控，对特定资费场景生成预警，为资费管理人员提供有力抓手；提供多种分析工具，结合各类展示方式，快速、灵活生成分析结果，为用户聚焦业务重点、把控收益提供数据支撑；形成产品配置模板库，实现结构化产品需求设计，减少人工干预，提升了资费的初步梳理及管理，规范了资费相关的业务流程。', 1, NULL, NULL, '数智化部', NULL, NULL, '2022-06-01', '委外', NULL),
    ('SDYYBY0008-QC', '跨域系统视频服务支撑能力', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '客户与产品运营系统', '客户服务系统', 'IN_USE', '跨省视频台席以视频交互为连接入口，通过音视频双通道+统一交互协议，深度融合视频流、业务流、信息流，面向营业厅客户端、行销人员行网格通端提供跨省、跨地市、跨平台的多端异地协同交互能力， 实现“客户操作简单、一线使用便捷、系统承载复杂”的服务体验。', 1, NULL, NULL, '数智化部', '程文雅', '19725317180', '2022-12-01', '委外', NULL),
    ('SDYYBY0017-QC', '能力开放平台', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '中台运营支撑系统', '中台运营支撑系统', 'IN_USE', '省级能力开放平台', 1, NULL, NULL, '数智化部', NULL, NULL, '2017-07-01', '委外', NULL),
    ('SDYYBY0028-QC', '谛听智慧客户服务系统', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '大数据应用系统', '其他大数据应用系统', 'IN_USE', '基于大数据打造智慧客户服务解决方案，打造面向全体客户的满意度运营体系，重在量化评估、协同运营。通过数据挖掘与分析，建设标准模型体系。融通网络侧、服务侧、业务侧数据，综合分析发掘潜在不满用户，协助互联网中心、客服部进行客户关怀营销，提升客户满意度，降投诉、增价值。', 1, NULL, NULL, '数智化部', NULL, NULL, '2020-03-01', '委外', NULL),
    ('SDYYBY0018-QC', '山东移动合作伙伴管理系统', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '客户与产品运营系统', 'CRM系统', 'IN_USE', '主要是对合作伙伴的数据进行管理，包括合作伙伴基本信息管理，合作伙伴生态画像的管理，合作伙伴退库，合作伙伴的评审等相关的操作；合作伙伴招募流程是实现合作伙伴的招募流程管理，包括招募需求，招募方案，招募公告，招募应答信息，招募评审，招募伙伴入库等相关操作，通过招募流程可以实现合作伙伴的入库；合作伙伴甄选流程，是实现了合作伙伴甄选流程管理，包括甄选需求，甄选方案，甄选方案决策，甄选公告，甄选评审，甄选公示，甄选复核，甄选流程归档等。合作伙伴专家信息管理，专家部门管理，场景管理。', 1, NULL, NULL, '数智化部', NULL, NULL, '2022-06-01', '委外', NULL),
    ('SDYYBY0016-QC', '图分析应用平台', NULL, '山东公司', '应用系统', '业务支撑系统（B域）', '大数据应用系统', '其他大数据应用系统', 'IN_USE', '基于图数据库支撑的图分析应用平台，支撑诈骗号码实时预警、移动高清大屏内容实时推荐等实时图推荐能力；支撑一人多号识别、集团成员真实性判断等离线模型。', 1, NULL, NULL, '数智化部', NULL, NULL, '2016-10-01', '委外', NULL),
