    ('SDYYOY0056-QC', '资源管理系统（外线管理）', '传输管线系统', '山东公司', '应用系统', '网管系统（O域）', '网管平台', '资源管理系统', 'IN_USE', '传输管线系统是“2+5+N”网管架构中5个能力中心之一，与综资共同构成网络资源中心。目前主要实现对光缆、人井、管道等哑资源数据的管理，并通过建立资源入网/变更/退网等管理流程，不断提升哑资源数据质量，支撑业务发展。', 0, '国讯新创', NULL, '网络管理中心', NULL, NULL, '2025-03-01', '委外', NULL),
    ('SDYYOY0053-QC', 'IP网运维工作台', 'SDN流量调优系统', '山东公司', '应用系统', '网管系统（O域）', '专业运维', '专业运维工作台', 'IN_USE', 'SDN控制提供IGP 路由拓扑、路由监控、路由分析及路由告警功能、提供 BGP 路由拓扑、路由监控、路由分析及路由告警功能；基于 XFLOW 采集流量流向数据，实现用户、业务、网络多维度，以及网络级、链路级和对象级的流量成分分析，结合路由及流量数据，对网络流量分布及流量路径进行可视化呈现。', 0, '中盈优创', NULL, '网络管理中心', NULL, NULL, '2025-03-01', '委外', NULL),
    ('SDYYOY0057-QC', '无线网运维工作台', '无线网运维工作台（设计院）', '山东公司', '应用系统', '网管系统（O域）', '专业运维', '专业运维工作台', 'IN_USE', '主要支撑无线运维工作的基站自动开通、无线网络性能分析、能耗管控等功能。', 0, '设计院、东联', NULL, '网络优化中心', NULL, NULL, '2025-03-01', '委外', NULL),
    ('SDSZAI0005-QC', '数字员工运营管理平台', NULL, '山东公司', '数智化基础平台', 'AI平台', 'AI平台', 'AI平台', 'IN_USE', NULL, 1, NULL, NULL, '数智化部', NULL, NULL, '2024-10-01', '委外', NULL),
    ('SDYYOY0041-QC', '传输网运维工作台', '传输网工作台', '山东公司', '应用系统', '网管系统（O域）', '专业运维', '专业运维工作台', 'IN_USE', '传输运维工作台定位于重点实现传输专业的下行自动配置、传输网络的自动操作维护及分析优化；实现传输专业的内线资源管理、配置下发、割接管理、远程巡检、质量分析优化、网络测试等功能。从部署层级上分，传输运维工作台分为总部、省级两级部署，各省传输运维工作台应能配合总部传输运维工作台实现传输网络的全程调度，并具备与总部传输运维工作台的简单数据接口，实现网络概况、运维质量、结构评估等数据的定期自动汇总，以减少手工填报，提高部省协同效率', 0, '中移设计院、直真', NULL, '网络管理中心', NULL, NULL, '2025-03-01', '委外', NULL),
    ('SDYYOY0059-QC', '网管研运工作台', '网络知识图谱平台', '山东公司', '应用系统', '网管系统（O域）', '专业运维', '专业运维工作台', 'IN_USE', '主要通过搭建网络运维知识中心，构建统一的智能体知识库支撑体系，提供标准化API接口对接智能体，实现运维知识的集中管理和高效复用，提升网络运维效率。', 0, '网思', NULL, '网络管理中心', NULL, NULL, '2025-03-01', '委外', NULL),
    ('SDYYOY0045-QC', '质量管理系统', '网络价值运营模块、移网质量管理模块（含物联网）、家客质量管理模块', '山东公司', '应用系统', '网管系统（O域）', '网管平台', '质量管理系统', 'IN_USE', '网络价值运营平台对于网络价值进行运营管理，包括流量激发、网络产品变现管理等。
移网质量管理系统是2+5+N网管系统架构的质量管理中心之一，构建移动网网络性能、业务质量、用户感知的端到端质量管理能力，开展端到端网络质量评估及闭环管理工作，支撑自智网络AN能力提升。面向VoLTE/EPSFB/VoNR等语音业务，视频/游戏/浏览/支付/即时通信等数据业务，5G消息/点对点短信/行业短信业务、政企5G专网/物联网业务，实现质差用户、质差业务、质差地理位置、质差网元的识别与定界，打造“质差主动发现、全程定界、仿真验证、优化闭环”的端到端客户体验主动运维能力。
家客质量管理系统是“2+5+N”网管架构中5个能力中心之一，主要支撑家庭宽带客户网络质量可视、可管、可控的端到端质量分析系统，具体包括用户质量画像、质差监测分析、网络故障分析、终端质量管理，质量专题分析、AN场景等重点建设，实现家宽业务质量分析及闭环管控', 0, '名通、中兴、宜通、东信、飞思达', NULL, '网络管理中心', NULL, NULL, '2025-03-01', '委外', NULL);

